def convert_interval(s_in, s_op, func):
    """Return range of kmers or filtering ratios.

    """
    msg = 'bad {}: {} {}'
    try:
        s = list(map(func, s_in.split(':')))
    except:
        raise Exception(msg.format('value', s_op, s_in))
    if len(s) == 1:
        return s
    if len(s) == 3:
        beg, end, interval = s
        values = []
        while beg < end:
            values.append(beg)
            beg += interval
        values.append(end)
        return values
    else:
        raise Exception(msg.format('interval', s_op, s_in))

