def get_pos_hash_gff(path):
    """Returns a dictionary that maps coordinates to a list of genes that occur at that coordinate.

    Arguments:
        path (str): Path to annotation in GFF3 format.

    Returns:
        dict: Dictionary of position to list of genes that share that position.
    """
    hash = {}
    for line in open(path):
        if line.startswith('#'):
            continue
        tmp = line.strip().split('\t')
        features = dict([tuple(f.split('=', 1)) for f in filter(lambda x: 
            '=' in x, tmp[8].split(';'))])
        if 'ID' not in features:
            continue
        orf = features['ID']
        chr = tmp[0]
        type = tmp[2]
        start = int(tmp[3])
        end = int(tmp[4])
        for pos in range(start, end + 1):
            if pos not in hash:
                hash[pos] = []
            hash[pos].append(orf)
    return hash

