class Equation:
    def __init__(self, compounds):
        # compounds: list of (compound_id, stoich), negative stoich for reactants, positive for products
        self.compounds = compounds
    def __str__(self):
        reac = [f"{abs(v)} {c}" if abs(v) != 1 else c for c, v in self.compounds if v < 0]
        prod = [f"{abs(v)} {c}" if abs(v) != 1 else c for c, v in self.compounds if v > 0]
