def digest(sequence, enzyme, count_missed_cleavages=None,
    no_missed_cleavages=False):
    """
    Amino acid digest function

    Keyword Arguments:
        sequence (str): amino acid sequence to digest
        enzyme (tuple): enzyme properties used for cleavage ('aminoacid(s)', 'N/C(terminus)')
                        e.g. ('KR','C') for trypsin
        count_missed_cleavages (int): number of miss cleavages allowed

    Returns:
        list: list of digested peptides

    """
    tmp = ''
    result = []
    additionals = list()
    if count_missed_cleavages is None:
        if no_missed_cleavages is False:
            count_missed_cleavages = 2
        else:
            count_missed_cleavages = 0
    cleavage_aa, site = enzyme
    for p, aa in enumerate(sequence):
        if aa == '*':
            continue
        tmp += aa
        if aa in cleavage_aa:
            if site == 'C':
                result.append(tmp)
                tmp = ''
            elif site == 'N':
                result.append(tmp[0:len(tmp) - 1])
                tmp = ''
                tmp += aa
    if tmp != '':
        result.append(tmp)
    if count_missed_cleavages > len(result):
        count_missed_cleavages = len(result)
    if count_missed_cleavages == 0:
        additionals = result
    else:
        for r in range(len(result)):
            for mc in range(r, len(result) + 1):
                if mc - r >= count_missed_cleavages:
                    continue
                if mc + 2 > len(result):
                    continue
                newpep = ''.join(result[r:mc + 2])
                if newpep != '':
                    additionals.append(newpep)
        additionals += result
    return additionals

def _parse_tree(tstring, flags, internalNode_count, scale_tree, index):
    """
        Recursively parse a newick tree string and convert to a Node object. 
        Uses the functions _read_branch_length(), _read_leaf(), _read_model_flag() during the recursion.
    """
    assert tstring[index] == '('
    index += 1
    node = Node()
    while True:
        if tstring[index] == '(':
            subtree, flags, internalNode_count, index = _parse_tree(tstring,
                flags, internalNode_count, scale_tree, index)
            node.children.append(subtree)
        elif tstring[index] == ',':
            index += 1
        elif tstring[index] == ')':
            index += 1
            if index < len(tstring):
                if re.match('^[A-Za-z]', tstring[index]):
                    name, index = _read_node_name(tstring, index)
                    node.name = name
                if index == len(tstring):
                    node.root = True
                    break
                if tstring[index] == ':':
                    BL, index = _read_branch_length(tstring, index)
                    node.branch_length = BL
                if tstring[index] in MODEL_FLAGS:
                    (node.model_flag, node.propagate_model, flag_symbol, index
                        ) = _read_model_flag(tstring, index)
                    flags.append(node.model_flag)
            if node.name is None:
                if node.branch_length is None:
                    node.root = True
                    node.name = 'root'
                else:
                    node.name = 'internalNode' + str(internalNode_count)
                    internalNode_count += 1
                    node.branch_length *= scale_tree
            if node.root is False:
                assert node.branch_length is not None, """
Your tree is missing branch length(s). Please ensure that all nodes and tips have a branch length (even if the branch length is 0!)."""
            else:
                assert node.branch_length is None, '\nERROR: Your tree root has a branch length.'
            assert node.name is not None, """
Internal node name was neither provided nor assigned, which means your tree has not been properly formatted. Please ensure that you have provided a proper newick tree."""
            break
        else:
            subtree, index = _read_leaf(tstring, index)
            subtree.branch_length *= scale_tree
            node.children.append(subtree)
    return node, flags, internalNode_count, index

