# Helper functions to support the MST path search
def getAdjacencyList(graph):
    adj = {}
    for u, v in graph:
        adj.setdefault(u, []).append(v)
        adj.setdefault(v, []).append(u)
    return adj

def doBFS(graph, start):
    adj = getAdjacencyList(graph)
    visited = set([start])
    queue = [start]
    for node in queue:
        yield node
        for neigh in adj.get(node, []):
            if neigh not in visited:
                visited.add(neigh)
                queue.append(neigh)

def findOnePath(adj, start, end):
    queue = [[start]]
    visited = set([start])
    while queue:
        path = queue.pop(0)
        node = path[-1]
        if node == end:
            return path
        for neigh in adj.get(node, []):
            if neigh not in visited:
                visited.add(neigh)
                queue.append(path + [neigh])
    return None

