def read_fastq(path):
    with open(path) as fh:
        while True:
            title = fh.readline().strip()
            if not title:
                break
            seq = fh.readline().strip()
            plus = fh.readline().strip()
            qual = fh.readline().strip()
            # strip leading '@'
