class tz:
    @staticmethod
    def partition_all(n, iterable):
        """Yield successive n-sized chunks from iterable"""
        it = iter(iterable)
        while True:
            chunk = []
            try:
                for _ in range(n):
                    chunk.append(next(it))
            except StopIteration:
                if chunk:
                    yield chunk
                break
            yield chunk

