def _calc_overlap(x, y, seed):
    """Return an overlapping position between a pair of k-mers.

    """
    if not x or not y:
        return 0
    for m in re.finditer(y[:seed], x):
        overlap = seed
        p = m.end()
        if len(x) == p:
            return overlap
        tail = re.search(x[p:], y)
        if not tail:
            continue
        if tail.start() == seed:
            return tail.end()
    return 0

