def group_by_genes(subprobes, skip_low):
    rows = []
    for gene, group in subprobes.groupby('gene'):
        total_weight = group['weight'].sum()
        total_probes = group['probes'].sum()
        if skip_low and total_probes < 2:
            continue
        rows.append({'gene': gene, 'weight': total_weight, 'probes': total_probes})
