    def biweight_midvariance(arr):
        M = np.median(arr)
        MAD = np.median(np.abs(arr - M))
        u = (arr - M) / (9 * MAD)
        mask = np.abs(u) < 1
        u_masked = u[mask]
        arr_masked = arr[mask]
