class Reaction:
    def __init__(self, direction, stoichiometry):
        self.direction = direction
        self.stoichiometry = stoichiometry
    def __eq__(self, other):
        return isinstance(other, Reaction) and self.direction == other.direction and self.stoichiometry == other.stoichiometry
    def __hash__(self):
        items = tuple(sorted(self.stoichiometry.items(), key=lambda x: (x[0].id, x[0].compartment)))
        return hash((self.direction, items))
    def __repr__(self):
        terms = ' + '.join(f"{v} {k}" for k, v in self.stoichiometry.items())
