def create_exchange_id(existing_ids, compound):
    base = f"EX_{compound.id}_{compound.compartment}"
    if base not in existing_ids:
        return base
    i = 1
    while f"{base}_{i}" in existing_ids:
        i += 1
    return f"{base}_{i}"

