# Helper: compute ranges of indices matching each interval
def idx_ranges(src_rows, starts, ends, mode):
    for s, e in zip(starts, ends):
        if mode == 'inner':
            mask = (src_rows['start'] >= s) & (src_rows['end'] <= e)
        else:
            mask = (src_rows['end'] >= s) & (src_rows['start'] <= e)
        # find positional locations in src_rows
        matching = src_rows.index[mask]
        slc = [src_rows.index.get_loc(i) for i in matching]
        yield slc, s, e

