# Define minimal stubs for PSAMM-like classes and helpers
class Direction:
    Both = 'both'

class Reaction:
    def __init__(self, direction, stoichiometry):
        self.direction = direction
        self.stoichiometry = stoichiometry
    def __eq__(self, other):
        return (self.direction == other.direction and
                self.stoichiometry == other.stoichiometry)
    def __hash__(self):
        items = tuple(sorted(self.stoichiometry.items(), key=lambda x: (x[0].id, x[1])))
        return hash((self.direction, items))

def create_transport_id(existing_ids, comp1, comp2):
    base = f"T_{comp1.id}_{comp1.compartment}_{comp2.compartment}"
    id_ = base
    count = 1
    while id_ in existing_ids:
        id_ = f"{base}_{count}"
        count += 1
    return id_

