        self._rxn_map = {}
    def get_reaction(self, rxnid):
        return self._rxn_map[rxnid]
    def set_reaction(self, rxnid, reaction):
        self._rxn_map[rxnid] = reaction
        self.reactions.add(rxnid)

class MetabolicModel:
