def getHTSeqCountVersion():
    """
    Tries to find the HTSeqCount binary
    and makes a system call to get its
    version and return it
    """
    version = ''
    try:
        proc = subprocess.Popen(['pip', 'show', 'htseq'], stdout=subprocess
            .PIPE, stderr=subprocess.PIPE, shell=False, close_fds=True)
        stdout, errmsg = proc.communicate()
        for line in stdout.split('\n'):
