class Formula:
    def __init__(self, composition=None):
        self.comp = composition.copy() if composition else {}
    def __rmul__(self, other):
        # allow int * Formula
        return Formula({el: other * cnt for el, cnt in self.comp.items()})
    def __or__(self, other):
        # combine two formulas by summing counts
        new = Formula(self.comp)
        for el, cnt in other.comp.items():
            new.comp[el] = new.comp.get(el, 0) + cnt
        return new
    def __repr__(self):
