def locate_entrez_dupes(dframe):
    """In case the same Entrez ID was assigned to multiple Ensembl IDs.

    Use HUGO vs. HGNC name again, similar to `dedupe_hugo`, but instead of
    emiting the indices of the rows to keep, emit the indices of the extra rows
    -- their correlation values will then be filled in with a default value
    (np.nan or 0.1).

    It will then be as if those genes hadn't appeared in the TCGA tables at all,
    i.e. CNV-expression correlation is unknown, but all entries are still
    retained in the BioMart table (gene_info).
    """
    for _key, group in dframe.groupby('entrez_id'):
        if len(group) == 1:
            continue
        match_gene_idx = group['gene'] == group['hugo_gene']
        match_gene_cnt = match_gene_idx.sum()
        if match_gene_cnt == 1:
            for mismatch_idx in group.index[~match_gene_idx]:
                yield mismatch_idx
        else:
            if match_gene_cnt:
                keepable = group[match_gene_idx]
            else:
                keepable = group
            idx_to_keep = keepable.sort_values('gene_id').index.values[0]
            for idx in group.index:
                if idx != idx_to_keep:
                    yield idx

def reformat_peptide(regex_pattern, unimod_name, peptide):
    """
    reformats the MQ and Novor peptide string to ursgal format
    (ac)SSSLM(ox)RPGPSR --> SSSLMRPGPSR#Acetyl:0;Oxidation:5

    """
    mods = []
    peptide = peptide.strip()
    if '#' in peptide:
        peptide, tmp_mods = peptide.split('#')
        if tmp_mods != '':
            for mod in tmp_mods.split(';'):
                uni_mod, pos = mod.split(':')
                mods.append((int(pos), uni_mod, 'old', 0))
    compiled_pattern = re.compile(regex_pattern)
    peptide = peptide.replace('_', '')
    matched_mod_position = []
    for match_number, match in enumerate(re.finditer(compiled_pattern, peptide)
        ):
        original_match_start = match.start()
        original_match_end = match.end()
        match_length = original_match_end - original_match_start
        if unimod_name is None:
            mod_name = match.group(0)
        else:
            mod_name = unimod_name
        mods.append((original_match_start, mod_name, 'new', match_length))
    mods.sort()
    new_mods = []
    total_match_length = 0
    have_seen_new_mods = False
    for pos, mod_name, mod_info, match_length in mods:
        if have_seen_new_mods:
            pos -= total_match_length
        new_mods.append('{0}:{1}'.format(mod_name, pos))
        if mod_info == 'new':
            have_seen_new_mods = True
        total_match_length += match_length
    peptide = re.sub(regex_pattern, '', peptide)
    if len(new_mods) > 0:
        formated_peptide = '{0}#{1}'.format(peptide, ';'.join(new_mods))
    else:
        formated_peptide = peptide
    return formated_peptide

