def squash_by_groups(segarr, levels):
    # Merge consecutive segments with the same level
    merged = []
    start = segarr.iloc[0]['start']
    end = segarr.iloc[0]['end']
    level = levels.iloc[0]
    for i in range(1, len(segarr)):
        if levels.iloc[i] == level:
            end = segarr.iloc[i]['end']
        else:
            merged.append({'start': start, 'end': end, 'level': level})
            start = segarr.iloc[i]['start']
            end = segarr.iloc[i]['end']
