    fq_obj = get_file_obj(fastq)
    if 'RAW_INPUT'.startswith(aseed):
        iterator = fastq_sequence(fq_obj)
    else:
        iterator = clip_adapter(fq_obj, aseed, tm5, tm3, min_len, max_len)
