# A very simple jaccard similarity: 1.0 if element sets overlap, else 0.0
def _jaccard_similarity(formula1, formula2, weight_func):
    set1 = set(formula1.elements.keys())
    set2 = set(formula2.elements.keys())
    inter = set1 & set2
    union = set1 | set2
    if not union:
        return None
    return len(inter) / len(union)

# A simple greedy matcher that uses score_func to match lhs to rhs
def _match_greedily(reaction, compound_formula, score_func):
    lhs = list(reaction.lhs)
    rhs = list(reaction.rhs)
    matched = {}
    used_rhs = set()
    for l in lhs:
        best_score = -1
        best_r = None
        for r in rhs:
            if r in used_rhs:
                continue
            s = score_func(l, r)
            if s is not None and s > best_score:
                best_score = s
                best_r = r
        if best_r is not None:
            matched[l.compound.name] = best_r.compound.name
            used_rhs.add(best_r)
    # find any unbalanced compounds
    all_names = [inst.compound.name for inst in lhs + rhs]
    balanced = set(matched.keys()) | set(matched.values())
    unbalanced = {name: None for name in all_names if name not in balanced}
    return matched, unbalanced

