def reaction_charge(equation, compound_charge):
    """
    Compute net charge for a single reaction equation.
    equation: string like 'A + 2 B -> C + D'
    compound_charge: dict mapping compound id to its charge
    Returns product_charge_sum - reactant_charge_sum
    """
    reactants_str, products_str = equation.split('->')
    def sum_side(side_str):
        total = 0
        for term in side_str.split('+'):
            term = term.strip()
            parts = term.split()
            if len(parts) == 1:
                coef = 1.0
                cid = parts[0]
            else:
                # assume format '2 B' or 'B 2'
                try:
                    # try coefficient first
                    coef = float(parts[0])
                    cid = parts[1]
                except ValueError:
                    # try coefficient last
                    coef = float(parts[-1])
                    cid = parts[0]
            total += compound_charge.get(cid, 0) * coef
        return total
    return sum_side(products_str) - sum_side(reactants_str)

