def parse_fasta(io):
    """
    Small function to efficiently parse a file in fasta format.

    Keyword Arguments:
        io (obj): openend file obj (fasta file)

    Yields:
        tuple: fasta_id and sequence
    """
    id = None
    sequence = ''
    for line in io:
        line = line.strip()
        if line == '':
            continue
        if line[0] == '>':
            if id:
                yield id, sequence
            id = line[1:].strip()
            sequence = ''
        else:
            sequence += line
    if id:
        yield id, sequence

