def _parse_tree(tstring, flags, internalNode_count, scale_tree, index):
    """
        Recursively parse a newick tree string and convert to a Node object. 
        Uses the functions _read_branch_length(), _read_leaf(), _read_model_flag() during the recursion.
    """
    assert tstring[index] == '('
    index += 1
    node = Node()
    while True:
        if tstring[index] == '(':
            subtree, flags, internalNode_count, index = _parse_tree(tstring,
                flags, internalNode_count, scale_tree, index)
            node.children.append(subtree)
        elif tstring[index] == ',':
            index += 1
        elif tstring[index] == ')':
            index += 1
            if index < len(tstring):
                if re.match('^[A-Za-z]', tstring[index]):
                    name, index = _read_node_name(tstring, index)
                    node.name = name
                if index == len(tstring):
                    node.root = True
                    break
                if tstring[index] == ':':
                    BL, index = _read_branch_length(tstring, index)
                    node.branch_length = BL
                if tstring[index] in MODEL_FLAGS:
                    (node.model_flag, node.propagate_model, flag_symbol, index
                        ) = _read_model_flag(tstring, index)
                    flags.append(node.model_flag)
            if node.name is None:
                if node.branch_length is None:
                    node.root = True
                    node.name = 'root'
                else:
                    node.name = 'internalNode' + str(internalNode_count)
                    internalNode_count += 1
                    node.branch_length *= scale_tree
            if node.root is False:
                assert node.branch_length is not None, """
Your tree is missing branch length(s). Please ensure that all nodes and tips have a branch length (even if the branch length is 0!)."""
            else:
                assert node.branch_length is None, '\nERROR: Your tree root has a branch length.'
            assert node.name is not None, """
Internal node name was neither provided nor assigned, which means your tree has not been properly formatted. Please ensure that you have provided a proper newick tree."""
            break
        else:
            subtree, index = _read_leaf(tstring, index)
            subtree.branch_length *= scale_tree
            node.children.append(subtree)
    return node, flags, internalNode_count, index

def check_args(args):
    """Checks the arguments and options.

    Args:
        args (argparse.Namespace): the options to verify

    Note
    ----
        If there is a problem, a :py:class:`genipe.error.GenipeError` is
        raised.

    """
    for filename in args.impute2:
        if not os.path.isfile(filename):
            raise GenipeError('{}: no such file'.format(filename))
        summary_file = filename + '_summary'
        if not os.path.isfile(summary_file):
            raise GenipeError('{}: no such file'.format(summary_file))
        info_file = filename + '_info'
        if not os.path.isfile(info_file):
            raise GenipeError('{}: no such file'.format(info_file))
        with open(info_file, 'r') as i_file:
            header = set(i_file.readline().rstrip('\r\n').split(' '))
            for name in ('rs_id', 'position', 'info'):
                if name not in header:
                    raise GenipeError("{}: missing column '{}'".format(
                        info_file, name))
    valid_chromosome = [str(i) for i in range(1, 24)]
    valid_chromosome.append('25')
    if args.chrom not in valid_chromosome:
        raise GenipeError('{}: invalid chromosome'.format(args.chrom))
    if args.chrom == '23':
        logging.warning(
            'MAF computation is wrong for chromosome 23 (males have 2 alleles in the computation, instead of 1)...'
            )
    if args.probability < 0 or args.probability > 1:
        raise GenipeError('{}: invalid probability'.format(args.probability))
    if args.completion < 0 or args.completion > 1:
        raise GenipeError('{}: invalid completion'.format(args.completion))
    if args.info < 0 or args.info > 1:
        raise GenipeError('{}: invalid info'.format(args.info))
    return True
